-- Cairnly Encore v2 survey (spec: docs/encore-v2-question-ids.md, copy approved at gate A on 2026-11-10).
-- Fully additive: new survey id ...0004, section/question ids c3c3c3c3-... . Encore v1 (...0003, b2b2b2b2-...),
-- Pro and Starter rows are untouched. Dutch copy uses "u" and lives in translations.nl (display only);
-- stored answer values stay the English choice strings. 7.2 (check-in consent) is reserved and NOT inserted.
-- No new tables, so no Data API grants are needed.

INSERT INTO public.surveys (id, title)
VALUES ('00000000-0000-0000-0000-000000000004', 'Encore - Post-Career Direction - 2026 v2')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.survey_sections (id, survey_id, title, description, order_num, translations) VALUES
  ('c3c3c3c3-0000-4000-a000-000000000001', '00000000-0000-0000-0000-000000000004', 'About you', 'A few basics, so the advice fits your life.', 1, '{"nl": {"title": "Over u", "description": "Een paar basisgegevens, zodat het advies past bij uw leven."}}'::jsonb),
  ('c3c3c3c3-0000-4000-a000-000000000002', '00000000-0000-0000-0000-000000000004', 'Your working life', 'What you did, and what you''d like to keep from it.', 2, '{"nl": {"title": "Uw werkzame leven", "description": "Wat u deed, en wat u daarvan wilt meenemen."}}'::jsonb),
  ('c3c3c3c3-0000-4000-a000-000000000003', '00000000-0000-0000-0000-000000000004', 'Being useful', 'The heart of it: what being useful looks like for you.', 3, '{"nl": {"title": "Van betekenis zijn", "description": "De kern: hoe van betekenis zijn er voor u uitziet."}}'::jsonb),
  ('c3c3c3c3-0000-4000-a000-000000000004', '00000000-0000-0000-0000-000000000004', 'What suits you', 'How you like to spend your time and energy.', 4, '{"nl": {"title": "Wat bij u past", "description": "Hoe u uw tijd en energie het liefst besteedt."}}'::jsonb),
  ('c3c3c3c3-0000-4000-a000-000000000005', '00000000-0000-0000-0000-000000000004', 'The people around you', 'Your partner, your friends, and who you''d like to do things with.', 5, '{"nl": {"title": "De mensen om u heen", "description": "Uw partner, uw vrienden, en met wie u dingen wilt doen."}}'::jsonb),
  ('c3c3c3c3-0000-4000-a000-000000000006', '00000000-0000-0000-0000-000000000004', 'Fitting it into your life', 'Time, place and money, so the options are realistic.', 6, '{"nl": {"title": "Inpassen in uw leven", "description": "Tijd, plaats en geld, zodat de mogelijkheden haalbaar zijn."}}'::jsonb),
  ('c3c3c3c3-0000-4000-a000-000000000007', '00000000-0000-0000-0000-000000000004', 'To finish', 'One last question, and room for anything else.', 7, '{"nl": {"title": "Tot slot", "description": "Nog één vraag, en ruimte voor wat u verder kwijt wilt."}}'::jsonb)
ON CONFLICT (id) DO NOTHING;

-- ============ Section 1: About you ============
INSERT INTO public.questions (id, section_id, type, label, required, allow_multiple, allow_other, order_num, min_selections, max_selections, config, translations) VALUES
  ('c3c3c3c3-0001-4000-a000-000000000001', 'c3c3c3c3-0000-4000-a000-000000000001', 'short_text', 'What is your first name?', true, false, false, 1, NULL, NULL,
   '{}'::jsonb,
   '{"nl": {"label": "Wat is uw voornaam?"}}'::jsonb),
  ('c3c3c3c3-0001-4000-a000-000000000002', 'c3c3c3c3-0000-4000-a000-000000000001', 'number', 'How old are you?', true, false, false, 2, NULL, NULL,
   '{}'::jsonb,
   '{"nl": {"label": "Hoe oud bent u?"}}'::jsonb),
  ('c3c3c3c3-0001-4000-a000-000000000003', 'c3c3c3c3-0000-4000-a000-000000000001', 'dropdown', 'Where do you live?', true, false, false, 3, NULL, NULL,
   '{"description": "So we can suggest options near you.", "choices": ["Northern and Western Europe", "Southern and Eastern Europe", "United Kingdom (London)", "United Kingdom (Other)", "United States (High-Cost Regions)", "United States (Average-Cost Regions)", "United States (Lower-Cost Regions)", "Canada", "Australia and New Zealand", "Switzerland"]}'::jsonb,
   '{"nl": {"label": "Waar woont u?", "description": "Zo kunnen we mogelijkheden bij u in de buurt voorstellen."}}'::jsonb),
  ('c3c3c3c3-0001-4000-a000-000000000004', 'c3c3c3c3-0000-4000-a000-000000000001', 'multiple_choice', 'Where are you in your working life?', true, false, false, 4, NULL, NULL,
   '{"choices": ["Still working, I stop in more than a year", "Still working, I stop within a year", "Working less, step by step", "Stopped less than a year ago", "Stopped one to three years ago", "Stopped more than three years ago", "I run my own business and want to step back"]}'::jsonb,
   '{"nl": {"label": "Waar staat u in uw werkzame leven?", "choices": {"Still working, I stop in more than a year": "Ik werk nog, en stop over meer dan een jaar", "Still working, I stop within a year": "Ik werk nog, en stop binnen een jaar", "Working less, step by step": "Ik ga stap voor stap minder werken", "Stopped less than a year ago": "Ik ben minder dan een jaar geleden gestopt", "Stopped one to three years ago": "Ik ben een tot drie jaar geleden gestopt", "Stopped more than three years ago": "Ik ben meer dan drie jaar geleden gestopt", "I run my own business and want to step back": "Ik heb een eigen bedrijf en wil een stap terug doen"}}}'::jsonb),
  ('c3c3c3c3-0001-4000-a000-000000000005', 'c3c3c3c3-0000-4000-a000-000000000001', 'multiple_choice', 'Whose decision is it to stop working?', true, false, false, 5, NULL, NULL,
   '{"choices": ["My own", "Partly mine", "It was decided for me, for example in a reorganisation", "Nothing is decided yet"]}'::jsonb,
   '{"nl": {"label": "Van wie komt de beslissing om te stoppen met werken?", "choices": {"My own": "Van mijzelf", "Partly mine": "Deels van mij", "It was decided for me, for example in a reorganisation": "Er is voor mij besloten, bijvoorbeeld bij een reorganisatie", "Nothing is decided yet": "Er is nog niets besloten"}}}'::jsonb)
ON CONFLICT (id) DO NOTHING;

-- ============ Section 2: Your working life ============
INSERT INTO public.questions (id, section_id, type, label, required, allow_multiple, allow_other, order_num, min_selections, max_selections, config, translations) VALUES
  ('c3c3c3c3-0002-4000-a000-000000000001', 'c3c3c3c3-0000-4000-a000-000000000002', 'career_history', 'Which roles shaped your working life?', true, false, false, 1, NULL, NULL,
   '{"description": "Up to 4 roles. For each: the role, the organisation, start and end year, and a few words on what you did there (type or speak). Paid and unpaid work both count, including years spent caring for family. Speak other languages? Mention them in any box. If you uploaded your CV, we filled this in: check it and add what matters to you.", "slim": true, "maxRoles": 4}'::jsonb,
   '{"nl": {"label": "Welke functies hebben uw werkzame leven gevormd?", "description": "Maximaal 4 functies. Per functie: de functie, de organisatie, het begin- en eindjaar, en een paar woorden over wat u er deed (typen of inspreken). Betaald en onbetaald werk tellen allebei mee, ook jaren waarin u voor familie zorgde. Spreekt u andere talen? Noem ze in een van de vakken. Heeft u uw cv geüpload? Dan hebben we dit al ingevuld: controleer het en vul aan wat voor u belangrijk is."}}'::jsonb),
  ('c3c3c3c3-0002-4000-a000-000000000002', 'c3c3c3c3-0000-4000-a000-000000000002', 'multiple_choice', 'What were you known for at work?', true, true, true, 2, NULL, 5,
   '{"description": "What colleagues came to you for. Pick up to 5.", "choices": ["Explaining things clearly", "Organising and planning", "Listening and giving advice", "Solving practical problems", "Leading a team", "Bringing people together", "Numbers and money", "Writing", "Selling and convincing", "Making or building things", "Looking after people", "Spotting risks early", "Starting new things"]}'::jsonb,
   '{"nl": {"label": "Waar stond u om bekend op uw werk?", "description": "Waarvoor collega''s bij u kwamen. Kies er maximaal 5.", "choices": {"Explaining things clearly": "Dingen helder uitleggen", "Organising and planning": "Organiseren en plannen", "Listening and giving advice": "Luisteren en advies geven", "Solving practical problems": "Praktische problemen oplossen", "Leading a team": "Een team leiden", "Bringing people together": "Mensen bij elkaar brengen", "Numbers and money": "Cijfers en geld", "Writing": "Schrijven", "Selling and convincing": "Verkopen en overtuigen", "Making or building things": "Dingen maken of bouwen", "Looking after people": "Voor mensen zorgen", "Spotting risks early": "Risico''s vroeg zien", "Starting new things": "Nieuwe dingen opzetten"}}}'::jsonb),
  ('c3c3c3c3-0002-4000-a000-000000000003', 'c3c3c3c3-0000-4000-a000-000000000002', 'long_text', 'What did you love about your work?', true, false, false, 3, NULL, NULL,
   '{"description": "The parts you would gladly do again, even unpaid. For example: \"Sitting down with a new colleague and seeing it click.\"", "max_length": 1500}'::jsonb,
   '{"nl": {"label": "Wat vond u het mooiste aan uw werk?", "description": "De dingen die u graag opnieuw zou doen, zelfs onbetaald. Bijvoorbeeld: \"Met een nieuwe collega gaan zitten en zien dat het kwartje valt.\""}}'::jsonb),
  ('c3c3c3c3-0002-4000-a000-000000000004', 'c3c3c3c3-0000-4000-a000-000000000002', 'multiple_choice', 'What are you glad to leave behind?', true, true, true, 4, NULL, 3,
   '{"description": "Pick up to 3.", "choices": ["Long meetings", "Office politics", "Targets and reviews", "Commuting", "Being on call", "Fixed hours", "A lot of travel", "Pressure and deadlines", "Managing people", "Not much, I liked it all"], "exclusive_choices": ["Not much, I liked it all"]}'::jsonb,
   '{"nl": {"label": "Wat laat u graag achter zich?", "description": "Kies er maximaal 3.", "choices": {"Long meetings": "Lange vergaderingen", "Office politics": "Machtsspelletjes op het werk", "Targets and reviews": "Targets en beoordelingen", "Commuting": "Woon-werkverkeer", "Being on call": "Altijd bereikbaar moeten zijn", "Fixed hours": "Vaste werktijden", "A lot of travel": "Veel reizen", "Pressure and deadlines": "Druk en deadlines", "Managing people": "Leidinggeven", "Not much, I liked it all": "Niet veel, ik vond het allemaal mooi"}}}'::jsonb)
ON CONFLICT (id) DO NOTHING;

-- ============ Section 3: Being useful ============
INSERT INTO public.questions (id, section_id, type, label, required, allow_multiple, allow_other, order_num, min_selections, max_selections, config, translations) VALUES
  ('c3c3c3c3-0003-4000-a000-000000000001', 'c3c3c3c3-0000-4000-a000-000000000003', 'multiple_choice', 'Which of these feels most true for you right now?', true, false, false, 1, NULL, NULL,
   '{"description": "Pick the one that comes closest.", "choices": ["I want to stay useful, but not in a job like my old one. I don''t know what fits me.", "Work gave my week its shape. I''m not sure what will replace it.", "Most of my contacts came through work. I don''t want to lose that.", "My partner and I need to figure this out together.", "None of these. I mostly want to make the most of the coming years."]}'::jsonb,
   '{"nl": {"label": "Wat past op dit moment het best bij u?", "description": "Kies wat het dichtst in de buurt komt.", "choices": {"I want to stay useful, but not in a job like my old one. I don''t know what fits me.": "Ik wil van betekenis blijven, maar niet in een baan zoals mijn oude. Ik weet niet wat bij mij past.", "Work gave my week its shape. I''m not sure what will replace it.": "Mijn werk gaf mijn week vorm. Ik weet niet goed wat daarvoor in de plaats komt.", "Most of my contacts came through work. I don''t want to lose that.": "De meeste van mijn contacten kwamen via mijn werk. Die wil ik niet kwijtraken.", "My partner and I need to figure this out together.": "Mijn partner en ik moeten dit samen uitzoeken.", "None of these. I mostly want to make the most of the coming years.": "Geen van deze. Ik wil vooral het beste maken van de komende jaren."}}}'::jsonb),
  ('c3c3c3c3-0003-4000-a000-000000000002', 'c3c3c3c3-0000-4000-a000-000000000003', 'long_text', 'When did you feel most useful?', true, false, false, 2, NULL, NULL,
   '{"description": "At work or outside it, recently or long ago. What were you doing, and for whom? For example: \"Coaching the youth team at our hockey club.\"", "max_length": 1500}'::jsonb,
   '{"nl": {"label": "Wanneer voelde u zich het meest van betekenis?", "description": "Op uw werk of daarbuiten, onlangs of lang geleden. Wat deed u, en voor wie? Bijvoorbeeld: \"Het jeugdteam van onze hockeyclub trainen.\""}}'::jsonb),
  ('c3c3c3c3-0003-4000-a000-000000000003', 'c3c3c3c3-0000-4000-a000-000000000003', 'multiple_choice', 'Who would you most like to be useful to?', true, true, false, 3, NULL, 3,
   '{"description": "Pick up to 3.", "choices": ["One person at a time, like a student or a starter", "A team or organisation", "Young people", "People going through a hard time", "My own field or profession", "My town or neighbourhood", "A cause, like nature, culture or health", "My family", "Myself, by making or learning something"]}'::jsonb,
   '{"nl": {"label": "Voor wie zou u het liefst van betekenis zijn?", "description": "Kies er maximaal 3.", "choices": {"One person at a time, like a student or a starter": "Eén persoon tegelijk, zoals een student of een starter", "A team or organisation": "Een team of organisatie", "Young people": "Jongeren", "People going through a hard time": "Mensen die het moeilijk hebben", "My own field or profession": "Mijn eigen vakgebied", "My town or neighbourhood": "Mijn woonplaats of buurt", "A cause, like nature, culture or health": "Een goed doel, zoals natuur, cultuur of gezondheid", "My family": "Mijn familie", "Myself, by making or learning something": "Mijzelf, door iets te maken of te leren"}}}'::jsonb),
  ('c3c3c3c3-0003-4000-a000-000000000004', 'c3c3c3c3-0000-4000-a000-000000000003', 'multiple_choice', 'Which of these would you like to explore?', true, true, false, 4, NULL, NULL,
   '{"description": "Pick all that appeal. Board and supervisory roles come with legal duties; your report explains what that means.", "choices": ["Paid work, part time or per project", "Interim or freelance work in my field", "A board, supervisory or advisory role", "Mentoring or coaching", "Teaching or training", "Volunteering", "Starting something small of my own", "Learning something new", "I don''t know yet, show me what fits"], "exclusive_choices": ["I don''t know yet, show me what fits"]}'::jsonb,
   '{"nl": {"label": "Wat zou u willen verkennen?", "description": "Kies alles wat u aanspreekt. Bestuurs- en toezichtsfuncties brengen wettelijke plichten mee; uw rapport legt uit wat dat betekent.", "choices": {"Paid work, part time or per project": "Betaald werk, in deeltijd of per project", "Interim or freelance work in my field": "Interim- of freelancewerk in mijn vakgebied", "A board, supervisory or advisory role": "Een bestuurs-, toezichts- of adviesfunctie", "Mentoring or coaching": "Mentor of coach zijn", "Teaching or training": "Lesgeven of trainen", "Volunteering": "Vrijwilligerswerk", "Starting something small of my own": "Iets kleins voor mezelf beginnen", "Learning something new": "Iets nieuws leren", "I don''t know yet, show me what fits": "Ik weet het nog niet, laat zien wat past"}}}'::jsonb),
  ('c3c3c3c3-0003-4000-a000-000000000005', 'c3c3c3c3-0000-4000-a000-000000000003', 'long_text', 'Is there something you already tried, or an idea you keep coming back to?', false, false, false, 5, NULL, NULL,
   '{"description": "Tell us how it went. Skip this if nothing comes to mind.", "max_length": 1500}'::jsonb,
   '{"nl": {"label": "Heeft u al iets geprobeerd, of is er een idee waar u steeds op terugkomt?", "description": "Vertel hoe het ging. Sla deze vraag over als er niets bij u opkomt."}}'::jsonb)
ON CONFLICT (id) DO NOTHING;

-- ============ Section 4: What suits you ============
INSERT INTO public.questions (id, section_id, type, label, required, allow_multiple, allow_other, order_num, min_selections, max_selections, config, translations) VALUES
  ('c3c3c3c3-0004-4000-a000-000000000001', 'c3c3c3c3-0000-4000-a000-000000000004', 'multiple_choice', 'After a day with lots of people, how do you feel?', true, false, false, 1, NULL, NULL,
   '{"choices": ["Full of energy", "Good, but I need some quiet after", "A bit tired", "Drained, I need time alone"]}'::jsonb,
   '{"nl": {"label": "Hoe voelt u zich na een dag met veel mensen?", "choices": {"Full of energy": "Vol energie", "Good, but I need some quiet after": "Goed, maar daarna heb ik wat rust nodig", "A bit tired": "Een beetje moe", "Drained, I need time alone": "Leeg, ik heb tijd voor mezelf nodig"}}}'::jsonb),
  ('c3c3c3c3-0004-4000-a000-000000000002', 'c3c3c3c3-0000-4000-a000-000000000004', 'multiple_choice', 'What should your week look like?', true, false, false, 2, NULL, NULL,
   '{"choices": ["Fixed days and set appointments", "A steady rhythm with room to move", "Free, I commit per project or season", "Completely open"]}'::jsonb,
   '{"nl": {"label": "Hoe ziet uw week er het liefst uit?", "choices": {"Fixed days and set appointments": "Vaste dagen en vaste afspraken", "A steady rhythm with room to move": "Een vast ritme met ruimte om te schuiven", "Free, I commit per project or season": "Vrij, ik zeg per project of seizoen toe", "Completely open": "Helemaal open"}}}'::jsonb),
  ('c3c3c3c3-0004-4000-a000-000000000003', 'c3c3c3c3-0000-4000-a000-000000000004', 'multiple_choice', 'Which role suits you best?', true, false, false, 3, NULL, NULL,
   '{"choices": ["Leading, taking charge", "Doing, rolling up my sleeves", "Advising, being the sounding board", "Teaching, helping someone grow", "Connecting, bringing people together", "It depends on the setting"]}'::jsonb,
   '{"nl": {"label": "Welke rol past het best bij u?", "choices": {"Leading, taking charge": "Leiden, de leiding nemen", "Doing, rolling up my sleeves": "Doen, de handen uit de mouwen steken", "Advising, being the sounding board": "Adviseren, een klankbord zijn", "Teaching, helping someone grow": "Onderwijzen, iemand helpen groeien", "Connecting, bringing people together": "Verbinden, mensen bij elkaar brengen", "It depends on the setting": "Dat hangt van de situatie af"}}}'::jsonb),
  ('c3c3c3c3-0004-4000-a000-000000000004', 'c3c3c3c3-0000-4000-a000-000000000004', 'multiple_choice', 'What matters most to you in the coming years?', true, true, false, 4, 3, 3,
   '{"description": "Pick 3.", "choices": ["Being useful to others", "Keeping my mind busy", "Having people around me", "A rhythm to my week", "My experience being valued", "Some extra income", "Freedom for travel and family", "Making or building something", "Giving back to a cause", "Learning something new"]}'::jsonb,
   '{"nl": {"label": "Wat vindt u de komende jaren het belangrijkst?", "description": "Kies er 3.", "choices": {"Being useful to others": "Van betekenis zijn voor anderen", "Keeping my mind busy": "Mijn hoofd bezig houden", "Having people around me": "Mensen om me heen", "A rhythm to my week": "Ritme in mijn week", "My experience being valued": "Dat mijn ervaring gewaardeerd wordt", "Some extra income": "Wat extra inkomen", "Freedom for travel and family": "Vrijheid voor reizen en familie", "Making or building something": "Iets maken of opbouwen", "Giving back to a cause": "Iets teruggeven aan een goed doel", "Learning something new": "Iets nieuws leren"}}}'::jsonb)
ON CONFLICT (id) DO NOTHING;

-- ============ Section 5: The people around you ============
INSERT INTO public.questions (id, section_id, type, label, required, allow_multiple, allow_other, order_num, min_selections, max_selections, config, translations) VALUES
  ('c3c3c3c3-0005-4000-a000-000000000001', 'c3c3c3c3-0000-4000-a000-000000000005', 'multiple_choice', 'How do your plans relate to your partner''s?', true, false, false, 1, NULL, NULL,
   '{"choices": ["We make plans together", "We each do our own thing, and that works", "We haven''t really talked about it yet", "We want different things", "I don''t have a partner"]}'::jsonb,
   '{"nl": {"label": "Hoe verhouden uw plannen zich tot die van uw partner?", "choices": {"We make plans together": "We maken samen plannen", "We each do our own thing, and that works": "We doen ieder ons eigen ding, en dat werkt", "We haven''t really talked about it yet": "We hebben er nog niet echt over gepraat", "We want different things": "We willen verschillende dingen", "I don''t have a partner": "Ik heb geen partner"}}}'::jsonb),
  ('c3c3c3c3-0005-4000-a000-000000000002', 'c3c3c3c3-0000-4000-a000-000000000005', 'long_text', 'What does your partner hope for in the coming years?', false, false, false, 2, NULL, NULL,
   '{"description": "In their words, if you can. Skip this if it doesn''t apply.", "max_length": 1500}'::jsonb,
   '{"nl": {"label": "Waar hoopt uw partner op voor de komende jaren?", "description": "In de woorden van uw partner, als dat lukt. Sla deze vraag over als die niet van toepassing is."}}'::jsonb),
  ('c3c3c3c3-0005-4000-a000-000000000003', 'c3c3c3c3-0000-4000-a000-000000000005', 'multiple_choice', 'How do you feel about the people around you?', true, false, false, 3, NULL, NULL,
   '{"choices": ["I have plenty of good people around me", "Enough, but new contacts would be welcome", "I miss the daily contact from work", "I''d like to meet people in the same phase of life"]}'::jsonb,
   '{"nl": {"label": "Hoe kijkt u aan tegen de mensen om u heen?", "choices": {"I have plenty of good people around me": "Ik heb genoeg goede mensen om me heen", "Enough, but new contacts would be welcome": "Genoeg, maar nieuwe contacten zijn welkom", "I miss the daily contact from work": "Ik mis het dagelijkse contact van mijn werk", "I''d like to meet people in the same phase of life": "Ik zou graag mensen in dezelfde levensfase ontmoeten"}}}'::jsonb),
  ('c3c3c3c3-0005-4000-a000-000000000004', 'c3c3c3c3-0000-4000-a000-000000000005', 'multiple_choice', 'Do you like to do things on your own or with others?', true, false, false, 4, NULL, NULL,
   '{"choices": ["On my own", "With one or two others", "As part of a group", "It doesn''t matter"]}'::jsonb,
   '{"nl": {"label": "Doet u dingen liever alleen of met anderen?", "choices": {"On my own": "Alleen", "With one or two others": "Met een of twee anderen", "As part of a group": "In een groep", "It doesn''t matter": "Dat maakt me niet uit"}}}'::jsonb)
ON CONFLICT (id) DO NOTHING;

-- ============ Section 6: Fitting it into your life ============
INSERT INTO public.questions (id, section_id, type, label, required, allow_multiple, allow_other, order_num, min_selections, max_selections, config, translations) VALUES
  ('c3c3c3c3-0006-4000-a000-000000000001', 'c3c3c3c3-0000-4000-a000-000000000006', 'multiple_choice', 'How much time would you like to spend on what comes next?', true, false, false, 1, NULL, NULL,
   '{"choices": ["A few hours a month", "Half a day a week", "One or two days a week", "Three days or more", "It depends on the season"]}'::jsonb,
   '{"nl": {"label": "Hoeveel tijd wilt u besteden aan wat hierna komt?", "choices": {"A few hours a month": "Een paar uur per maand", "Half a day a week": "Een halve dag per week", "One or two days a week": "Een of twee dagen per week", "Three days or more": "Drie dagen of meer", "It depends on the season": "Dat hangt af van het seizoen"}}}'::jsonb),
  ('c3c3c3c3-0006-4000-a000-000000000002', 'c3c3c3c3-0000-4000-a000-000000000006', 'multiple_choice', 'What is already fixed in your calendar?', true, true, false, 2, NULL, NULL,
   '{"description": "Pick all that apply.", "choices": ["Days with grandchildren", "Caring for someone", "Long trips or winters abroad", "Clubs or volunteering I want to keep", "Nothing fixed"], "exclusive_choices": ["Nothing fixed"]}'::jsonb,
   '{"nl": {"label": "Wat staat al vast in uw agenda?", "description": "Kies alles wat van toepassing is.", "choices": {"Days with grandchildren": "Oppasdagen met kleinkinderen", "Caring for someone": "Zorg voor iemand", "Long trips or winters abroad": "Lange reizen of overwinteren in het buitenland", "Clubs or volunteering I want to keep": "Clubs of vrijwilligerswerk die ik wil houden", "Nothing fixed": "Niets vast"}}}'::jsonb),
  ('c3c3c3c3-0006-4000-a000-000000000003', 'c3c3c3c3-0000-4000-a000-000000000006', 'multiple_choice', 'Where would you like this to happen?', true, false, false, 3, NULL, NULL,
   '{"choices": ["From home, online", "Close to home", "Within an hour''s travel", "Anywhere, for the right thing"]}'::jsonb,
